import java.io.*;import java.net.*;import java.nio.file.*;
public final class RoomCards713ServerCheck {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS: "+s);}
 static int[] row(GunnyServer server,GunnyServer.Session viewer,int id)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();server.roomList(new DataOutputStream(bytes),viewer);DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes.toByteArray()));int n=in.readUnsignedShort();int[] result=null;for(int i=0;i<n;i++){int room=in.readInt();in.readUTF();int human=in.readUnsignedByte(),raw=in.readUnsignedByte(),phase=in.readUnsignedByte();boolean locked=viewer.async&&in.readBoolean();int kind=-1,map=-1,players=human,seats=raw;if(viewer.roomCards){kind=in.readUnsignedByte();map=in.readByte();players=in.readUnsignedByte();seats=in.readUnsignedByte();}if(room==id)result=new int[]{human,raw,phase,locked?1:0,kind,map,players,seats};}ok(in.available()==0,"Room list packet has no unexpected trailing bytes");return result;}
 public static void main(String[] args)throws Exception{CloudStore.Memory store=new CloudStore.Memory();try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){var host=Matchmaking680Check.person(store,90);var guest=Matchmaking680Check.person(store,91);var viewer=Matchmaking680Check.person(store,92);viewer.roomCards=true;var room=Matchmaking680Check.room(server,host,null);room.requestedMap=-1;room.map=4;int[] a=row(server,viewer,room.id);ok(a[4]==0&&a[5]==-1&&a[6]==1&&a[7]==2,"Private room card shows Free, Random and 1/2 despite reserved enemy slots");room.closedSlots|=4;a=row(server,viewer,room.id);ok(a[6]==1&&a[7]==1&&a[3]==0,"Closing the ally slot produces 1/1 without a password-lock icon");room.closedSlots&=~4;room.secret="abc123";a=row(server,viewer,room.id);ok(a[6]==1&&a[7]==2&&a[3]==1,"Password-protected open room remains 1/2 with password lock");room.members[2]=guest;room.refreshWaiting();a=row(server,viewer,room.id);ok(a[6]==2&&a[7]==2,"Joining ally updates actual occupancy to 2/2");room.members[2]=null;a=row(server,viewer,room.id);ok(a[6]==1,"A departed member is not counted from a stale portrait/avatar");room.allyBot=3;room.refreshWaiting();a=row(server,viewer,room.id);ok(a[6]==2&&a[7]==2,"An AI occupying the ally slot is included");room.allyBot=-1;room.requestedMap=1;room.map=1;room.refreshWaiting();a=row(server,viewer,room.id);ok(a[5]==1,"Selected map ID is carried with the card");room.requestedMap=-1;room.map=5;a=row(server,viewer,room.id);ok(a[5]==-1,"Random mode does not leak the server's resolved map as a fixed choice");viewer.roomCards=false;a=row(server,viewer,room.id);ok(a[0]==1&&a[1]==4&&a[4]==-1,"Legacy card packet retains the original human-count/capacity prefix");viewer.roomCards=true;var team=server.new Room(host,2,2,-1,true);team.kind=2;team.strict=true;team.closedSlots=16;team.selectedBots[2]=2;team.refreshWaiting();server.rooms.put(team.id,team);a=row(server,viewer,team.id);ok(a[4]==2&&a[5]==2&&a[6]==2&&a[7]==5,"Challenge card counts AI and only the open seats in 3v3");}System.out.println("All room card 7.1.3 server checks passed");}
}
